+'use client';
+
+import React, { useState } from 'react';
+import { useToast } from '@/components/providers/toast-provider';
+
+/**
+ * Categories Page - CRUD Operations with Toast Notifications
+ *
+ * This page demonstrates toast notification integration for category
+ * management operations including create, update, and delete.
+ */
+
+interface Category {
+  id: string;
+  name: string;
+  description: string;
+}
+
+export default function CategoriesPage() {
+  const { showToast } = useToast();
+  const [categories, setCategories] = useState<Category[]>([]);
+  const [isCreating, setIsCreating] = useState(false);
+  const [isEditing, setIsEditing] = useState<string | null>(null);
+  const [formData, setFormData] = useState({
+    name: '',
+    description: '',
+  });
+
+  /**
+   * Validate form data
+   */
+  const validateForm = (): boolean => {
+    if (!formData.name.trim()) {
+      showToast('Category name is required', 'error', {
+        title: 'Validation Error',
+      });
+      return false;
+    }
+
+    if (!formData.description.trim()) {
+      showToast('Category description is required', 'error', {
+        title: 'Validation Error',
+      });
+      return false;
+    }
+
+    return true;
+  };
+
+  /**
+   * Create new category
+   */
+  const handleCreate = async () => {
+    if (!validateForm()) return;
+
+    setIsCreating(true);
+
+    try {
+      // Simulate API call
+      await new Promise((resolve) => setTimeout(resolve, 500));
+
+      const newCategory: Category = {
+        id: crypto.randomUUID(),
+        name: formData.name,
+        description: formData.description,
+      };
+
+      setCategories([...categories, newCategory]);
+
+      // ✅ Show success toast instead of inline message
+      showToast('Category created successfully', 'success');
+
+      // Reset form
+      setFormData({ name: '', description: '' });
+    } catch (error) {
+      // ✅ Show error toast instead of inline message
+      showToast('Failed to create category. Please try again.', 'error', {
+        title: 'Error',
+      });
+    } finally {
+      setIsCreating(false);
+    }
+  };
+
+  /**
+   * Update existing category
+   */
+  const handleUpdate = async (categoryId: string) => {
+    if (!validateForm()) return;
+
+    try {
+      // Simulate API call
+      await new Promise((resolve) => setTimeout(resolve, 500));
+
+      setCategories(
+        categories.map((c) =>
+          c.id === categoryId
+            ? {
+                ...c,
+                name: formData.name,
+                description: formData.description,
+              }
+            : c
+        )
+      );
+
+      // ✅ Show success toast
+      showToast('Category updated successfully', 'success');
+
+      // Reset editing state
+      setIsEditing(null);
+      setFormData({ name: '', description: '' });
+    } catch (error) {
+      // ✅ Show error toast
+      showToast('Failed to update category. Please try again.', 'error', {
+        title: 'Error',
+      });
+    }
+  };
+
+  /**
+   * Delete category
+   */
+  const handleDelete = async (categoryId: string, categoryName: string) => {
+    // Optional: Show confirmation dialog first
+    if (!window.confirm(`Are you sure you want to delete "${categoryName}"?`)) {
+      return;
+    }
+
+    try {
+      // Simulate API call
+      await new Promise((resolve) => setTimeout(resolve, 300));
+
+      setCategories(categories.filter((c) => c.id !== categoryId));
+
+      // ✅ Show success toast
+      showToast(`Category "${categoryName}" deleted`, 'success');
+    } catch (error) {
+      // ✅ Show error toast
+      showToast('Failed to delete category. Please try again.', 'error', {
+        title: 'Error',
+      });
+    }
+  };
+
+  /**
+   * Start editing a category
+   */
+  const startEdit = (category: Category) => {
+    setIsEditing(category.id);
+    setFormData({
+      name: category.name,
+      description: category.description,
+    });
+  };
+
+  /**
+   * Cancel editing
+   */
+  const cancelEdit = () => {
+    setIsEditing(null);
+    setFormData({ name: '', description: '' });
+  };
+
+  return (
+    <div className="container mx-auto px-4 py-8">
+      <h1 className="text-3xl font-bold mb-8">Categories Management</h1>
+
+      {/* Create Category Form */}
+      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6 mb-8">
+        <h2 className="text-xl font-semibold mb-4">
+          {isEditing ? 'Edit Category' : 'Create New Category'}
+        </h2>
+
+        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
+          <div>
+            <label htmlFor="name" className="block text-sm font-medium mb-1">
+              Category Name
+            </label>
+            <input
+              id="name"
+              type="text"
+              value={formData.name}
+              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
+              className="w-full px-3 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
+              placeholder="Enter category name"
+            />
+          </div>
+
+          <div>
+            <label htmlFor="description" className="block text-sm font-medium mb-1">
+              Description
+            </label>
+            <input
+              id="description"
+              type="text"
+              value={formData.description}
+              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
+              className="w-full px-3 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
+              placeholder="Enter description"
+            />
+          </div>
+        </div>
+
+        <div className="flex gap-2">
+          {isEditing ? (
+            <>
+              <button
+                onClick={() => handleUpdate(isEditing)}
+                className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
+              >
+                Update Category
+              </button>
+              <button
+                onClick={cancelEdit}
+                className="px-4 py-2 bg-gray-500 text-white rounded-md hover:bg-gray-600"
+              >
+                Cancel
+              </button>
+            </>
+          ) : (
+            <button
+              onClick={handleCreate}
+              disabled={isCreating}
+              className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 disabled:bg-gray-400"
+            >
+              {isCreating ? 'Creating...' : 'Create Category'}
+            </button>
+          )}
+        </div>
+
+        {/* ⚠️ NO INLINE ERROR DIVS - Using toast notifications instead */}
+      </div>
+
+      {/* Categories List */}
+      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
+        <h2 className="text-xl font-semibold mb-4">Categories List</h2>
+
+        {categories.length === 0 ? (
+          <p className="text-gray-500 text-center py-8">
+            No categories yet. Create your first category above.
+          </p>
+        ) : (
+          <div className="overflow-x-auto">
+            <table className="w-full">
+              <thead>
+                <tr className="border-b dark:border-gray-700">
+                  <th className="text-left py-3 px-4">Name</th>
+                  <th className="text-left py-3 px-4">Description</th>
+                  <th className="text-right py-3 px-4">Actions</th>
+                </tr>
+              </thead>
+              <tbody>
+                {categories.map((category) => (
+                  <tr
+                    key={category.id}
+                    className="border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700"
+                  >
+                    <td className="py-3 px-4">{category.name}</td>
+                    <td className="py-3 px-4">{category.description}</td>
+                    <td className="py-3 px-4 text-right">
+                      <button
+                        onClick={() => startEdit(category)}
+                        className="px-3 py-1 bg-blue-600 text-white text-sm rounded-md hover:bg-blue-700 mr-2"
+                      >
+                        Edit
+                      </button>
+                      <button
+                        onClick={() => handleDelete(category.id, category.name)}
+                        className="px-3 py-1 bg-red-600 text-white text-sm rounded-md hover:bg-red-700"
+                      >
+                        Delete
+                      </button>
+                    </td>
+                  </tr>
+                ))}
+              </tbody>
+            </table>
+          </div>
+        )}
+      </div>
+
+      {/* Information Panel */}
+      <div className="mt-8 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
+        <h3 className="font-semibold text-blue-900 dark:text-blue-100 mb-2">
+          ℹ️ Toast Notifications Integration
+        </h3>
+        <ul className="text-sm text-blue-800 dark:text-blue-200 space-y-1">
+          <li>✅ Success toasts shown for create, update, and delete operations</li>
+          <li>✅ Error toasts shown for validation failures and API errors</li>
+          <li>✅ No inline error divs - all feedback via toast notifications</li>
+          <li>✅ Toast messages are clear and actionable</li>
+          <li>✅ Optional titles provided for error context</li>
+        </ul>
+      </div>
+    </div>
+  );
+}

