+'use client';
+
+import React, { useState } from 'react';
+import { useToast } from '@/components/providers/toast-provider';
+
+/**
+ * Settings Page - User Preferences with Toast Notifications
+ *
+ * This is a reference implementation demonstrating how to integrate
+ * toast notifications into a settings/preferences page.
+ */
+
+interface SettingsFormData {
+  displayName: string;
+  email: string;
+  notifications: boolean;
+  theme: 'light' | 'dark' | 'system';
+  language: string;
+}
+
+export default function SettingsPage() {
+  const { showToast } = useToast();
+  const [isSaving, setIsSaving] = useState(false);
+  const [formData, setFormData] = useState<SettingsFormData>({
+    displayName: 'John Doe',
+    email: 'john.doe@example.com',
+    notifications: true,
+    theme: 'system',
+    language: 'en',
+  });
+
+  /**
+   * Validate form data
+   */
+  const validateForm = (): boolean => {
+    if (!formData.displayName.trim()) {
+      showToast('Display name is required', 'error', {
+        title: 'Validation Error',
+      });
+      return false;
+    }
+
+    if (!formData.email.trim()) {
+      showToast('Email is required', 'error', {
+        title: 'Validation Error',
+      });
+      return false;
+    }
+
+    // Basic email validation
+    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    if (!emailRegex.test(formData.email)) {
+      showToast('Please enter a valid email address', 'error', {
+        title: 'Validation Error',
+      });
+      return false;
+    }
+
+    return true;
+  };
+
+  /**
+   * Save settings
+   */
+  const handleSave = async (e: React.FormEvent) => {
+    e.preventDefault();
+
+    if (!validateForm()) return;
+
+    setIsSaving(true);
+
+    try {
+      // Simulate API call
+      await new Promise((resolve) => setTimeout(resolve, 800));
+
+      // ✅ Show success toast instead of inline message
+      showToast('Settings updated successfully', 'success');
+    } catch (error) {
+      // ✅ Show error toast instead of inline message
+      showToast('Failed to save settings. Please try again.', 'error', {
+        title: 'Error',
+      });
+    } finally {
+      setIsSaving(false);
+    }
+  };
+
+  /**
+   * Reset to defaults
+   */
+  const handleReset = () => {
+    // Optional: Show confirmation dialog first
+    if (!window.confirm('Are you sure you want to reset all settings to defaults?')) {
+      return;
+    }
+
+    setFormData({
+      displayName: 'John Doe',
+      email: 'john.doe@example.com',
+      notifications: true,
+      theme: 'system',
