+              placeholder="Enter your email"
+            />
+          </div>
+        </div>
+
+        {/* Preferences */}
+        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6 mb-6">
+          <h2 className="text-xl font-semibold mb-4">Preferences</h2>
+
+          {/* Notifications Toggle */}
+          <div className="mb-4 flex items-center">
+            <input
+              id="notifications"
+              type="checkbox"
+              checked={formData.notifications}
+              onChange={(e) =>
+                setFormData({ ...formData, notifications: e.target.checked })
+              }
+              className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
+            />
+            <label htmlFor="notifications" className="ml-2 text-sm font-medium">
+              Enable email notifications
+            </label>
+          </div>
+
+          {/* Theme Selection */}
+          <div className="mb-4">
+            <label htmlFor="theme" className="block text-sm font-medium mb-1">
+              Theme
+            </label>
+            <select
+              id="theme"
+              value={formData.theme}
+              onChange={(e) =>
+                setFormData({
+                  ...formData,
+                  theme: e.target.value as 'light' | 'dark' | 'system',
+                })
+              }
+              className="w-full px-3 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
+            >
+              <option value="light">Light</option>
+              <option value="dark">Dark</option>
+              <option value="system">System</option>
+            </select>
+          </div>
+
+          {/* Language Selection */}
+          <div className="mb-4">
+            <label htmlFor="language" className="block text-sm font-medium mb-1">
+              Language
+            </label>
+            <select
+              id="language"
+              value={formData.language}
+              onChange={(e) => setFormData({ ...formData, language: e.target.value })}
+              className="w-full px-3 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600"
+            >
+              <option value="en">English</option>
+              <option value="es">Español</option>
+              <option value="fr">Français</option>
+              <option value="de">Deutsch</option>
+            </select>
+          </div>
+        </div>
+
+        {/* Action Buttons */}
+        <div className="flex gap-3">
+          <button
+            type="submit"
+            disabled={isSaving}
+            className="px-6 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed"
+          >
+            {isSaving ? 'Saving...' : 'Save Settings'}
+          </button>
+
+          <button
+            type="button"
+            onClick={handleReset}
+            disabled={isSaving}
+            className="px-6 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400 disabled:bg-gray-200 disabled:cursor-not-allowed dark:bg-gray-600 dark:text-gray-200 dark:hover:bg-gray-500"
+          >
+            Reset to Defaults
+          </button>
+        </div>
+      </form>
+
+      {/* Toast Integration Information */}
+      <div className="mt-8 bg-blue-50 dark:bg-blue-900/20 rounded-lg p-6">
+        <h3 className="text-lg font-semibold mb-2 text-blue-900 dark:text-blue-100">
+          Toast Notification Integration
+        </h3>
+        <p className="text-sm text-blue-800 dark:text-blue-200 mb-3">
+          This settings page demonstrates toast notifications for:
+        </p>
+        <ul className="list-disc list-inside text-sm text-blue-800 dark:text-blue-200 space-y-1">
+          <li>
+            <strong>Success:</strong> Settings saved successfully
+          </li>
+          <li>
+            <strong>Error:</strong> Validation failures and save errors
+          </li>
+          <li>
+            <strong>Info:</strong> Settings reset to defaults
+          </li>
+          <li>
+            <strong>No inline error divs:</strong> All feedback through toasts
+          </li>
+        </ul>
+      </div>
+    </div>
+  );
+}

