index 0000000..f5868f3
--- /dev/null
+++ b/components/providers/toast-provider.tsx
@@ -0,0 +1,231 @@
+'use client';
+
+import React, { createContext, useContext, useState, useCallback, useRef, useEffect } from 'react';
+import { Toast, ToastContainer } from '@/components/ui/toast';
+
+/**
+ * Toast Notification Provider
+ *
+ * Provides global toast notification management across the application.
+ * Supports creating, displaying, and auto-dismissing toast notifications.
+ *
+ * @example
+ * ```tsx
+ * // In your app root
+ * <ToastProvider>
+ *   <YourApp />
+ * </ToastProvider>
+ *
+ * // In any component
+ * const { showToast } = useToast();
+ * showToast('Success!', 'success');
+ * ```
+ */
+
+// Toast data structure
+export interface ToastData {
+  /** Unique identifier for the toast */
+  id: string;
+  /** Toast variant/type */
+  variant: 'success' | 'error' | 'warning' | 'info';
+  /** Main message to display */
+  message: string;
+  /** Optional title */
+  title?: string;
+  /** Duration in milliseconds before auto-dismiss */
+  duration?: number;
+}
+
+// Options when creating a toast
+export interface ShowToastOptions {
+  /** Optional title for the toast */
+  title?: string;
+  /** Duration in milliseconds (default: 4000ms) */
+  duration?: number;
+}
+
+// Context value interface
+interface ToastContextValue {
+  /** Display a new toast notification */
+  showToast: (
+    message: string,
+    variant: 'success' | 'error' | 'warning' | 'info',
+    options?: ShowToastOptions
+  ) => void;
+  /** Remove a specific toast by ID */
+  removeToast: (id: string) => void;
+  /** Clear all active toasts */
+  clearAllToasts: () => void;
+  /** Array of currently active toasts */
+  toasts: ToastData[];
+}
+
+// Create context with undefined default (will throw error if used outside provider)
+const ToastContext = createContext<ToastContextValue | undefined>(undefined);
+
+// Maximum number of toasts to display at once
+const MAX_TOASTS = 5;
+// Default auto-dismiss duration
+const DEFAULT_DURATION = 4000;
+
+/**
+ * ToastProvider Component
+ *
+ * Wraps your application to provide toast notification functionality.
+ */
+export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
+  const [toasts, setToasts] = useState<ToastData[]>([]);
+  // Track auto-dismiss timers for each toast
+  const timersRef = useRef<Map<string, NodeJS.Timeout>>(new Map());
+
+  /**
+   * Remove a specific toast by ID
+   */
+  const removeToast = useCallback((id: string) => {
+    // Clear the timer for this toast
+    const timer = timersRef.current.get(id);
+    if (timer) {
+      clearTimeout(timer);
+      timersRef.current.delete(id);
+    }
+
+    // Remove from state
+    setToasts((prevToasts) => prevToasts.filter((toast) => toast.id !== id));
+  }, []);
+
+  /**
+   * Display a new toast notification
+   */
+  const showToast = useCallback(
+    (
+      message: string,
+      variant: 'success' | 'error' | 'warning' | 'info',
+      options?: ShowToastOptions
+    ) => {
+      const id = crypto.randomUUID();
+      const duration = options?.duration ?? DEFAULT_DURATION;
+
+      const newToast: ToastData = {
+        id,
+        variant,
+        message,
+        title: options?.title,
+        duration,
+      };
+
+      setToasts((prevToasts) => {
+        // Add new toast at the beginning
+        const updatedToasts = [newToast, ...prevToasts];
+
+        // Enforce maximum toast limit (FIFO - remove oldest)
+        if (updatedToasts.length > MAX_TOASTS) {
+          // Clear timers for removed toasts
+          const removedToasts = updatedToasts.slice(MAX_TOASTS);
+          removedToasts.forEach((toast) => {
+            const timer = timersRef.current.get(toast.id);
+            if (timer) {
+              clearTimeout(timer);
+              timersRef.current.delete(toast.id);
+            }
+          });
+
+          return updatedToasts.slice(0, MAX_TOASTS);
+        }
+
+        return updatedToasts;
+      });
+
+      // Set up auto-dismiss timer for this toast
+      if (duration > 0) {
+        const timer = setTimeout(() => {
+          removeToast(id);
+        }, duration);
+        timersRef.current.set(id, timer);
+      }
+    },
+    [removeToast]
+  );
+
+  /**
+   * Clear all active toasts
+   */
+  const clearAllToasts = useCallback(() => {
+    // Clear all timers
+    timersRef.current.forEach((timer) => clearTimeout(timer));
+    timersRef.current.clear();
+
+    // Clear all toasts
+    setToasts([]);
+  }, []);
+
+  /**
+   * Cleanup all timers on component unmount
+   */
+  useEffect(() => {
+    return () => {
+      // Clear all timers when component unmounts
+      timersRef.current.forEach((timer) => clearTimeout(timer));
+      timersRef.current.clear();
+    };
+  }, []);
+
+  const contextValue: ToastContextValue = {
+    showToast,
+    removeToast,
+    clearAllToasts,
+    toasts,
+  };
+
+  return (
+    <ToastContext.Provider value={contextValue}>
+      {children}
+
+      {/* Render ToastContainer with active toasts */}
+      {toasts.length > 0 && (
+        <ToastContainer>
+          {toasts.map((toast) => (
+            <Toast
+              key={toast.id}
+              variant={toast.variant}
+              message={toast.message}
+              title={toast.title}
+              onClose={() => removeToast(toast.id)}
+            />
+          ))}
+        </ToastContainer>
+      )}
+    </ToastContext.Provider>
+  );
+};
+
+/**
+ * useToast Hook
+ *
+ * Access toast notification functionality in any component.
+ * Must be used within a ToastProvider.
+ *
+ * @throws Error if used outside ToastProvider
+ *
+ * @example
+ * ```tsx
+ * const { showToast } = useToast();
+ *
+ * // Show success toast
+ * showToast('Product created successfully', 'success');
+ *
+ * // Show error toast with title
+ * showToast('Invalid input', 'error', { title: 'Validation Error' });
+ *
+ * // Show warning with custom duration
+ * showToast('Session expiring soon', 'warning', { duration: 8000 });
+ * ```
+ */
+export const useToast = (): ToastContextValue => {
+  const context = useContext(ToastContext);
+
+  if (context === undefined) {
+    throw new Error('useToast must be used within a ToastProvider');
+  }
+
+  return context;
+};

