+      aria-atomic="true"
+      className={`
+        flex items-start gap-3 p-4 rounded-lg border shadow-lg
+        ${config.bgColor}
+        ${config.borderColor}
+        animate-slide-in
+        max-w-md w-full
+        ${className}
+      `.trim()}
+    >
+      {/* Icon */}
+      <div className={`flex-shrink-0 ${config.iconColor}`}>
+        <Icon />
+      </div>
+
+      {/* Content */}
+      <div className="flex-1 min-w-0">
+        {title && (
+          <h3 className={`text-sm font-semibold mb-1 ${config.titleColor}`}>
+            {title}
+          </h3>
+        )}
+        <p className={`text-sm ${config.textColor}`}>
+          {message}
+        </p>
+      </div>
+
+      {/* Close button */}
+      <button
+        type="button"
+        onClick={onClose}
+        aria-label="Close notification"
+        className={`
+          flex-shrink-0 p-1 rounded-md transition-colors
+          ${config.iconColor}
+          ${config.closeHover}
+          focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-${variant}-500
+        `.trim()}
+      >
+        <CloseIcon />
+      </button>
+    </div>
+  );
+};
+
+/**
+ * ToastContainer Component
+ *
+ * Container for positioning and stacking multiple toast notifications.
+ * Fixed at top-right corner with proper spacing between toasts.
+ *
+ * @example
+ * ```tsx
+ * <ToastContainer>
+ *   <Toast variant="success" message="Success!" onClose={handleClose1} />
+ *   <Toast variant="error" message="Error!" onClose={handleClose2} />
+ * </ToastContainer>
+ * ```
+ */
+
+export interface ToastContainerProps {
+  /** Toast components to display */
+  children: React.ReactNode;
+  /** Additional CSS classes */
+  className?: string;
+}
+
+export const ToastContainer: React.FC<ToastContainerProps> = ({
+  children,
+  className = ''
+}) => {
+  return (
+    <div
+      className={`
+        fixed top-4 right-4 z-50
+        flex flex-col gap-3
+        pointer-events-none
+        max-w-md w-full
+        px-4 md:px-0
+        ${className}
+      `.trim()}
+    >
+      {React.Children.map(children, (child) => (
+        <div className="pointer-events-auto">
+          {child}
+        </div>
+      ))}
+    </div>
+  );
+};
